#!/usr/bin/env python3
"""Build the offline pose and motion browser beside the character-bank folders.

Run after exports: python source/build_motion_gallery.py [--root BANK_ROOT]
The page embeds its catalogue and file availability, but keeps art/video as
relative paths so the complete bank remains portable and works without a CDN.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path


def rows(catalog: dict, *keys: str) -> list[dict]:
    for key in keys:
        value = catalog.get(key)
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            return [{"id": k, **v} for k, v in value.items()]
    return []


def normalize(item: dict, kind: str) -> dict:
    identifier = item.get("id", item.get("slug", item.get("name", "")))
    if not identifier or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789_-" for c in identifier):
        raise ValueError(f"Unsafe or missing {kind} ID: {identifier!r}")
    result = dict(item)
    result["id"] = identifier
    result["label"] = item.get("label_ms", item.get("label", item.get("name_ms", item.get("name", identifier))))
    result["duration"] = item.get("duration_seconds", item.get("duration_s", item.get("duration", 0)))
    result["loop"] = item.get("loop", item.get("loopable", False))
    result["tags"] = item.get("tags", [])
    result["description"] = item.get("description_ms", item.get("description", item.get("notes", "")))
    return result


def build(root: Path) -> Path:
    roster = json.loads((root / "source/characters.json").read_text(encoding="utf-8"))
    catalog = json.loads((root / "source/motion_catalog.json").read_text(encoding="utf-8"))
    poses = [normalize(row, "pose") for row in rows(catalog, "poses", "pose_bank", "pose_library")]
    motions = [normalize(row, "motion") for row in rows(catalog, "motions", "actions", "motion_bank", "motion_library")]
    if not poses or not motions:
        raise ValueError("Catalogue must contain non-empty poses and motions lists")
    files = {}
    timings = {}
    for character in roster:
        cid = character["id"]
        timings[cid] = {}
        available = {"poses": {}, "motions": {}}
        for row in poses:
            available["poses"][row["id"]] = {
                suffix: f"poses/{cid}/{row['id']}.{suffix}"
                for suffix in ("svg", "png")
                if (root / f"poses/{cid}/{row['id']}.{suffix}").is_file()
            }
        for row in motions:
            aid = row["id"]
            paths = {"mp4": f"clips/{cid}/{aid}.mp4", "json": f"motions/{cid}/{aid}.json"}
            available["motions"][aid] = {key: path for key, path in paths.items() if (root / path).is_file()}
            if (root / paths["json"]).is_file():
                metadata = json.loads((root / paths["json"]).read_text(encoding="utf-8"))
                timings[cid][aid] = metadata.get("clip", {}).get("encoded_duration", metadata.get("duration_seconds", row["duration"]))
        front = f"assets/{cid}/front.svg"
        character["front_path"] = front if (root / front).is_file() else ""
        files[cid] = available
    counts = {
        "characters": len(roster),
        "pose_definitions": len(poses),
        "motion_definitions": len(motions),
        "pose_svgs": sum(bool(row.get("svg")) for char in files.values() for row in char["poses"].values()),
        "motion_mp4s": sum(bool(row.get("mp4")) for char in files.values() for row in char["motions"].values()),
        "motion_jsons": sum(bool(row.get("json")) for char in files.values() for row in char["motions"].values()),
    }
    payload = json.dumps({"characters": roster, "poses": poses, "motions": motions, "files": files, "timings": timings, "counts": counts}, ensure_ascii=False, separators=(",", ":"))
    for literal, escaped in (("&", "\\u0026"), ("<", "\\u003c"), (">", "\\u003e"), ("\u2028", "\\u2028"), ("\u2029", "\\u2029")):
        payload = payload.replace(literal, escaped)
    output = root / "Galeri_Pose_Gerakan.html"
    module_sources = {name: (root / "source" / name).read_text(encoding="utf-8") for name in ("character_renderer.cjs", "character_rig.cjs", "motion_library.cjs")}
    module_json = json.dumps(module_sources, ensure_ascii=False, separators=(",", ":"))
    for literal, escaped in (("&", "\\u0026"), ("<", "\\u003c"), (">", "\\u003e"), ("\u2028", "\\u2028"), ("\u2029", "\\u2029")):
        module_json = module_json.replace(literal, escaped)
    output.write_text(PAGE.replace("__DATA__", payload).replace("__MODULES__", module_json), encoding="utf-8")
    return output


